 const originalFactory=(()=>{const window={};
/**
 * Textos das fórmulas de Lotes; os cálculos executáveis ficam na API.
 */
(() => {
  const WEEKS = [7, 14, 21, 28, 35, 42];
  /**
   * FÓRMULA: Catálogo de fórmulas de Lotes
   * Gera textos dos cinco cards e três gráficos para os lotes que atingiram as semanas selecionadas. Não calcula os dados;
   * aponta para as funções documentadas de lotes.js.
   * Passo a passo (pseudocódigo):
   *   retornar descrições de contagem, soma, M+D, percentual e médias
   */
  window.buildLotesFormulas = (selected = WEEKS, filtered = false) => {
    const weeks = WEEKS.filter(week => selected.includes(week));
    const suffix = week => String(week).padStart(2, "0");
    const mortalityColumns = weeks.flatMap(week => ["Qtde Mort Sem-" + suffix(week), "Qtde Desc Sem-" + suffix(week)]);
    const weightColumns = weeks.map(week => "Peso Med.-" + suffix(week));
    const terms = weeks.map(week => `[Qtde Mort Sem-${suffix(week)}] + [Qtde Desc Sem-${suffix(week)}]`);
    const period = "Σ por lote (" + terms.join(" + ") + ")";
    const context = "Considera todos os filtros ativos da tela: Semana de avaliação (7, 14, 21, 28, 35 e 42 dias), Tipo de Granja, Produtor, Modelo, Galpão, Técnico e Mist Linha. A base usa somente lotes abertos com Data Recepcao nos últimos 45 dias; cada Codigo Granja + Num Lote + Galp + Data Recepcao aparece uma vez, na versão mais recente por Periodo_Arquivo_Fim.";
    const eligibility = "Para cada semana, use somente lotes que já atingiram essa idade. Inclui também lotes mais velhos, usando seus registros na semana escolhida. Somente as colunas selecionadas são calculadas, sem acumular semanas anteriores. Várias semanas formam uma união sem duplicar lotes.";
    const weeklyMeanLabels = weeks.map(week => `Média([Peso Med.-${suffix(week)}])`);
    const generalWeightFormula = weeklyMeanLabels.length
      ? `(${weeklyMeanLabels.join(" + ")}) / quantidade de médias semanais válidas`
      : "—";

    return [
      { id: "lotes_criacao", nome: "Lotes em Criação",
        formula_exibicao: "Contagem de combinações únicas de [Codigo Granja] + [Num Lote] + [Galp] + [Data Recepcao]",
        colunas: ["Codigo Granja", "Num Lote", "Galp", "Data Recepcao", "Periodo_Arquivo_Fim"],
        descricao: context, passos: ["Mantenha a versão mais recente de cada lote/galpão.", "Aplique a janela de 45 dias e os filtros selecionados.", eligibility, "Conte os lotes resultantes."] },
      { id: "aves_alojadas", nome: "Aves Alojadas", formula_exibicao: "Σ([Aves Inicia])",
        colunas: ["Aves Inicia"], descricao: context,
        passos: ["Use os mesmos lotes do card Lotes em Criação.", "Some a coluna [Aves Inicia] uma única vez por lote, mesmo ao selecionar várias semanas."] },
      { id: "mortalidade_qtde", nome: "Mortalidade no Período (Qtde)", formula_exibicao: period,
        colunas: mortalityColumns, descricao: "Mortes + descartes somente das semanas disponíveis: " + weeks.join(", ") + " dias.",
        passos: [eligibility, "Em cada lote, some as colunas de mortes e descartes das semanas disponíveis que o lote já atingiu.", "Some os resultados dos lotes. Campos vazios de mortes/descartes contam como zero."] },
      { id: "mortalidade", nome: "Mortalidade no Período (%)",
        formula_exibicao: "(" + period + " / Σ([Aves Inicia])) × 100",
        colunas: [...mortalityColumns, "Aves Inicia"], descricao: "Percentual do card e da tabela; utiliza a quantidade de mortes + descartes calculada acima.",
        passos: ["Some mortes + descartes das semanas disponíveis, respeitando a idade de cada lote.", "Divida pela soma de [Aves Inicia] dos lotes filtrados, contada apenas uma vez.", "Multiplique por 100. Se a soma de aves for zero, mostre —."] },
      { id: "peso_medio", nome: "Peso Médio Geral",
        formula_exibicao: generalWeightFormula,
        colunas: weightColumns,
        descricao: "Primeiro calcula a média simples de cada coluna semanal de peso no contexto filtrado. Depois soma as médias semanais válidas e divide pela quantidade de semanas com média disponível. Cada semana tem o mesmo peso no resultado geral, independentemente da quantidade de lotes daquela semana.",
        passos: [
          context,
          "Para cada semana disponível, mantenha somente lotes que já atingiram essa idade.",
          "Calcule separadamente a média dos valores válidos da coluna correspondente: por exemplo, 7 dias usa [Peso Med.-07] e 35 dias usa [Peso Med.-35].",
          "Se uma semana não tiver nenhum peso válido, ela não entra no numerador nem na quantidade de semanas.",
          "Some as médias semanais válidas e divida pela quantidade de médias semanais válidas. Não use Ps Pinto neste indicador."
        ] },
      { id: "mortalidade_semanal", nome: "Mortalidade Semanal",
        formula_exibicao: weeks.map(week => `${week} dias: Σ([Qtde Mort Sem-${suffix(week)}] + [Qtde Desc Sem-${suffix(week)}]) / Σ([Aves Inicia]) × 100`).join("\n"),
        colunas: [...mortalityColumns, "Aves Inicia", "Data Recepcao"],
        descricao: "Cada barra mostra a quantidade M + D da semana. Cada ponto da linha mostra o percentual dessa mesma semana. A linha tracejada representa a meta fixa de 1% no eixo de porcentagem; ela não altera as contas de mortalidade.",
        passos: ["Aplique todos os filtros ativos da tela.", "Para cada semana, selecione somente lotes que atingiram a idade correspondente.", "Some mortes + descartes da coluna dessa semana para obter a barra.", "Divida pelas aves iniciais desses mesmos lotes e multiplique por 100 para obter a linha. O denominador pode variar de uma semana para outra."] },
      { id: "peso_semanal", nome: "Média da Coluna de Peso por Idade",
        formula_exibicao: weeks.map(week => `${week} dias: Σ([Peso Med.-${suffix(week)}]) / quantidade de valores válidos em [Peso Med.-${suffix(week)}]`).join("\n"),
        colunas: weightColumns, descricao: "Cada idade é calculada separadamente. Ex.: 28 dias = média dos valores válidos da coluna [Peso Med.-28]; 35 dias = média dos valores válidos de [Peso Med.-35]. Todos os filtros ativos da tela são aplicados antes do cálculo.",
        passos: ["Aplique todos os filtros ativos da tela.", "Considere lotes que já atingiram a semana.", "Some os valores válidos da coluna correspondente e divida pela quantidade desses valores.", "Ignore campos vazios; zero preenchido continua sendo um valor."] },
      { id: "crescimento", nome: "Curva de Crescimento de Peso",
        formula_exibicao: "Cada ponto semanal usa a média da coluna correspondente: " + weightColumns.map(column => "[" + column + "]").join(", ") + ".",
        colunas: [...weightColumns, ...(!filtered ? ["Ps Pinto"] : [])],
        descricao: filtered ? "Mostra somente as semanas disponíveis com peso disponível, após aplicar todos os filtros da tela." : "O ponto 0 é Σ([Ps Pinto]) / quantidade de valores válidos de [Ps Pinto]. Os demais pontos usam as médias semanais após aplicar todos os filtros da tela.",
        passos: ["Aplique todos os filtros ativos da tela.", "Calcule cada ponto semanal como no gráfico Média da Coluna de Peso por Idade.", "Mostre somente pontos com peso válido. Não projete um peso para 45 dias, pois não existe essa coluna."] }
    ];
  };
  window.FORMULAS_LOTES = window.buildLotesFormulas();
})();

return window.buildLotesFormulas;})();
 const physical=column=>'mortalidade_peso_abertos.'+column.toLowerCase().replaceAll(' ','_').replaceAll('-','_').replaceAll('.','').replace('periodo_arquivo_fim','periodo_fim');
 const lotApi="def weekly(rows,config,weeks):\n    if config.get(\"weekly_partial_values\"):\n        return _weekly_partial(rows,config,weeks)\n    points=[]\n    for w in weeks:\n        eligible=[r for r in rows if not config.get(\"age_window\") or r.get(\"idade\",-1)>=w]\n        mortality_count=sum_column(eligible,f\"mort{w}\")\n        discard_count=sum_column(eligible,f\"disc{w}\")\n        deaths=mortality_count+discard_count\n        birds=sum_column(eligible,\"aves\")\n        points.append({\"idade\":w,\"mortes\":deaths,\"mortalidade\":ratio(deaths,birds,100),\"mortalidade_sem_descartes\":ratio(mortality_count,birds,100),\"descarte_percent\":ratio(discard_count,birds,100),\"peso\":mean([number(r.get(f\"peso{w}\")) for r in eligible]),\"lotes\":len(eligible)})\n    return points\n\ndef stats(rows,config,weeks):\n    if config.get(\"summary\"):\n        out={}\n        for key,spec in config[\"summary\"].items():\n            col=spec[\"column\"]\n            if spec[\"aggregation\"] == \"sum\": out[key]=sum_column(rows,col)\n            elif spec[\"aggregation\"] == \"count_nonzero\": out[key]=sum(1 for r in rows if number(r.get(col)) not in (None,Decimal(0)))\n            else: raise ValueError(\"Agregação não configurada.\")\n        rate=config.get(\"ratio\")\n        if rate: out[rate[\"id\"]]=ratio(out[rate[\"numerator\"]],out[rate[\"denominator\"]],rate[\"scale\"])\n        return out\n    birds=sum_column(rows,\"aves\")\n    points=weekly(rows,config,weeks)\n    if config.get(\"weekly_partial_values\"):\n        known_deaths=[p[\"mortes\"] for p in points if p[\"mortes\"] is not None]\n        deaths=sum(known_deaths,Decimal(0)) if known_deaths else None\n    else:\n        deaths=sum((p[\"mortes\"] for p in points),Decimal(0))\n    current=[]\n    for r in rows:\n        weight=number(r.get(\"peso_abate\"))\n        if weight is None:\n            weight=next((number(r.get(f\"peso{w}\"))/1000 for w in reversed(weeks) if number(r.get(f\"peso{w}\")) is not None),None)\n        current.append(weight)\n    result={\"lotes\":len(rows),\"aves\":birds,\"mortes\":deaths,\"mortalidade\":ratio(deaths,birds,100) if deaths is not None else None,\n            \"peso\":mean([p[\"peso\"] for p in points]),\"peso_atual\":mean(current)}\n    for field,column in config.get(\"mean_fields\",{}).items():\n        result[field]=mean([number(r.get(column)) for r in rows])\n    return result";
 function updateLots(weeks,filtered){
   const result=originalFactory(weeks,filtered);
   for(const item of result){
     const rules=[item.descricao];
     if(item.id==='mortalidade_semanal')rules.push('A meta exibida vem da resposta atual da API/cadastro de metas; não assumir 1% fixo sem o cadastro.');
     const entry={id:'lotes.'+item.id,title:item.nome,formula:item.formula_exibicao,description,
       columns:item.colunas.map(physical),steps:[...item.passos,'Sem denominador válido, apresentar —. Arredondar somente na exibição.'],rules,apiRule:lotApi,status:'padronizado',legacy:{}};
     if(item.id==='mortalidade_semanal')entry.rules[0]=entry.rules[0].replace('A linha tracejada representa a meta fixa de 1% no eixo de porcentagem; ela não altera as contas de mortalidade.','A linha tracejada representa a meta retornada pela API; ela não altera as contas de mortalidade.');
     entries.set(entry.id,entry);
   }
   return result.map(item=>legacy(entries.get('lotes.'+item.id)));
 }
 function legacy(entry){return {id:entry.id.split('.').slice(1).join('.'),nome:entry.title,coluna:entry.formula,formula_exibicao:entry.formula,descricao:entry.rules.join(' '),colunas:entry.columns,passos:entry.steps,...entry.legacy};}
 function legacyGroup(group){return [...entries.values()].filter(entry=>entry.id.startsWith(group+'.')).map(legacy);}
 updateLots();
 const screen=()=>location.pathname.endsWith('/detalhes.html')?'detalhes':document.body.dataset.page;
